(function ($) {
  'use strict';
  $.fn.imgNotes = function (options) {
    var image = this;
    var notes = options.notes || [];
    function render() {
      $('.note, .notep, .notesicon').remove();
      var offset = image.offset();
      if (!offset) return;
      notes.forEach(function (note) {
        var left = offset.left + Number(note.x1);
        var top = offset.top + Number(note.y1);
        var box = $('<div class="note"></div>')
          .attr('data-note-id', String(note.note_id || ''))
          .css({left: left + 'px', top: top + 'px', width: note.width + 'px', height: note.height + 'px'});
        var text = $('<div class="notep"></div>').text(note.note)
          .css({left: left + 'px', top: (top + Number(note.height) + 5) + 'px', whiteSpace: 'pre-wrap'});
        box.hover(function () { text.show().css('z-index', 10000); }, function () { text.hide(); });
        $('body').append(box).append(text);
      });
      if (options.isMobile === true) {
        var visible = false;
        $('<div class="notesicon"></div>').css({left: (offset.left + image.width() - 36) + 'px', top: (offset.top + image.height() - 40) + 'px'})
          .on('click', function () { visible = !visible; $.fn.imgNotes[visible ? 'showAll' : 'hideAll'](); }).appendTo('body');
      }
    }
    image.off('.imgNotes').on('mouseenter.imgNotes', function () { $('.note').show(); });
    // Replace rather than accumulate callbacks after repeated image load events.
    $(window).off('resize.imgNotes').on('resize.imgNotes', render);
    if (options.url) {
      $.getJSON(options.url, function (data) { notes = data; render(); });
    } else {
      render();
    }
    return image;
  };
  $.fn.imgNotes.showAll = function () { $('.note, .notep').show(); };
  $.fn.imgNotes.hideAll = function () { $('.note, .notep').hide(); };
})(jQuery);
